<?php $this->layout('default'); use Moves\Services\CmsAuth; use Moves\Services\CmsQuery as Q; use Moves\Services\PlatformBilling as B; use Moves\Support\CmsView as V;
$filters = ['q' => V::queryString('q'), 'status' => V::queryString('status')]; $result = B::subscriptions($filters, V::queryPage());
$plans = []; foreach (B::plans() as $p) { if ($p['status'] === 'active' && $p['price_id']) { $plans[$p['id']] = $p['name']; } }
$count = static fn (string $s): string => (string) Q::value('SELECT COUNT(*) FROM subscriptions WHERE status=?', [$s]); ?>
<?= V::kpis([['repeat', 'Ativas', $count('active'), 'contratos vigentes'], ['clock', 'Pendentes', $count('pending'), 'aguardando pagamento'], ['alert', 'Em atraso', $count('past_due'), 'com falha de pagamento'], ['trash', 'Canceladas', $count('canceled'), 'encerradas']]) ?>
<?php if (CmsAuth::can($admin, 'subscriptions.manage')): ?><details class="cms-card"><summary>Nova assinatura</summary><form method="post" action="/acao/subscription-create"><?= V::csrf() ?><div class="cms-form-grid"><?= V::field('E-mail do assinante', 'owner_email', '', ['type' => 'email', 'help' => 'Para pessoa física.']) ?><?= V::field('ID da empresa', 'organization_id', '', ['type' => 'number', 'help' => 'Preencha para assinatura empresarial.']) ?><?= V::field('Plano', 'plan_id', '', ['type' => 'select', 'choices' => $plans]) ?><?= V::field('Ciclo', 'billing_cycle', 'monthly', ['type' => 'select', 'choices' => ['monthly' => 'Mensal', 'annual' => 'Anual']]) ?></div><div class="cms-form-end"><button class="cms-btn-primary">Criar</button></div></form></details><?php endif; ?>
<section class="cms-list"><?= V::listHead('Lista de assinaturas', $result['total'] . ' registro(s)', V::searchForm('Buscar assinante', ['status' => [$filters['status'], ['' => 'Todas'] + V::SUB_STATUS, 'Situação']])) ?>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhuma assinatura encontrada.') ?><?php else: ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Assinaturas"><table><thead><tr><th>Assinante</th><th>Plano</th><th>Ciclo</th><th class="num">Valor contratado</th><th>Renovação</th><th>Status</th><th class="cms-th-actions">Ações</th></tr></thead><tbody><?php foreach ($result['rows'] as $s): ?><tr><td><a href="/assinaturas/<?= (int) $s['id'] ?>"><?= V::e($s['owner_name']) ?></a><br><small><?= V::e($s['owner_email'] ?? '') ?></small></td><td><?= V::e($s['plan_name']) ?></td><td><?= $s['billing_cycle'] === 'annual' ? 'Anual' : 'Mensal' ?></td><td class="num"><?= V::money($s['contracted_amount']) ?></td><td><?= V::date($s['renews_at'], false) ?></td><td><?= V::badge($s['status'], V::SUB_STATUS[$s['status']] ?? $s['status']) ?></td><td class="cms-td-actions"><?= V::iconLink('/assinaturas/' . (int) $s['id'], 'Abrir', 'eye') ?></td></tr><?php endforeach; ?></tbody></table></div><?= V::pager($result) ?><?php endif; ?></section>
